MakeShared.example:
#include <cinux/shared.hpp>
#include <type_traits>

using namespace cinux::base;

struct Frame : RefCount<> {
    int width;
    int height;
    Frame(int w, int h) : width(w), height(h) {}
};

void Example() {
    Shared<Frame> frame = MakeShared<Frame>(640, 480);
    // frame->width = 640，frame->height = 480，持有计数为 1
    static_assert(std::is_same_v<decltype(MakeShared<Frame>(640, 480)), Shared<Frame>>);

    frame.reset();  // 提前放掉这份持有，计数归零，Frame 随之删除
}

release.example:
#include <cinux/ref_count.hpp>
#include <type_traits>

using namespace cinux::base;

void Example() {
    RefCount<> counter;                       // 计数从 1 开始，属于第一个持有者
    counter.retain();                         // 借用方多持有一份，计数变成 2
    const bool borrowed = counter.release();  // 归还借来的那份，计数回到 1，返回 false
    const bool last = counter.release();      // 最后一份放掉，计数归零，返回 true
    static_assert(std::is_same_v<decltype(counter.release()), bool>);
}

PtrAt.example:
#include <cinux/ptr.hpp>
#include <type_traits>

using namespace cinux::base;

void Example() {
    auto* const kScreen = PtrAt<volatile unsigned short>(0xB8000UL);
    // kScreen 指向 0xB8000，文本模式显存的起点
    static_assert(std::is_same_v<decltype(PtrAt<volatile unsigned short>(0xB8000UL)),
                                 volatile unsigned short*>);
}
